  @override
  String alertsOverdue60(num count, String amount) {
    String _temp0 = intl.Intl.pluralLogic(
      count,
      locale: localeName,
      other: '$count ഉപഭോക്താക്കൾ',
      one: '$count ഉപഭോക്താവ്',
    );
    return '$_temp0 60 ദിവസത്തിലധികം പണമടയ്ക്കാൻ വൈകി: $amount';
  }

  @override
  String alertsGstOverdue(String form, String period, String days) {
    return '$period-ലെ $form $days ദിവസം വൈകി';
  }

  @override
  String alertsGstDue(String form, String period, String days) {
    return '$period-ലെ $form $days ദിവസത്തിനകം ഫയൽ ചെയ്യണം';
  }

  @override
  String alertsLowStock(num count) {
    String _temp0 = intl.Intl.pluralLogic(
      count,
      locale: localeName,
      other: '$count ഇനങ്ങൾ',
      one: '$count ഇനം',
    );
    return '$_temp0 റീഓർഡർ നിലയ്ക്ക് താഴെ';
  }

  @override
